				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$X_{c} = \frac{{f_{c} }}{{\sum\limits_{r = 1}^{20} {f_{r} + w\sum\limits_{j = 1}^{\uplambda } {\uptheta _{j} } } }}\,,\,\,\,\,\,\,\,\,\,\,(1 < c < 20)$$\end{document}Xc=fc∑r=120fr+w∑j=1λθj,(1<c<20)\documentclass[12pt]{minimal}
				\usepackage{amsmath}
				\usepackage{wasysym} 
				\usepackage{amsfonts} 
				\usepackage{amssymb} 
				\usepackage{amsbsy}
